-- Generated by svetra 0.6.0 from svetra.yaml (revision 9307cc55ae34). Do not edit.

-- Tables
create table "public"."post" (
  "id" uuid primary key default gen_random_uuid(),
  "author" uuid not null,
  "title" text not null,
  "is_public" boolean not null default false
);

-- Foreign keys
alter table "public"."post" add constraint "post_author_fkey" foreign key ("author") references "auth"."users" ("id");

-- Indexes
create index "post_author_idx" on "public"."post" ("author");

-- Access
alter table "public"."post" enable row level security;

-- Policies
create policy "public_posts_readable" on "public"."post"
  for select to anon, authenticated
  using ("is_public" = true);

create policy "authors_read_own" on "public"."post"
  for select to authenticated
  using ("author" = (select auth.uid()));

create policy "authors_write_own_insert" on "public"."post"
  for insert to authenticated
  with check ("author" = (select auth.uid()));

create policy "authors_write_own_update" on "public"."post"
  for update to authenticated
  using ("author" = (select auth.uid()))
  with check ("author" = (select auth.uid()));

create policy "authors_write_own_delete" on "public"."post"
  for delete to authenticated
  using ("author" = (select auth.uid()));
